// state = /LIGHT=ON, /LAMP=OFF, /FAN=ON, /ALL=OFF
const state = String(msg.req.query.state || "");
if (!/^\/(ALL|LIGHT|LAMP|FAN)=(ON|OFF)$/.test(state)) {
    msg.statusCode = 400;
    msg.payload = "Invalid state";
    return [null, msg];
}
msg.url = "http://" + flow.get("esp_ip") + state;
msg.method = "GET";
msg.requestTimeout = 1500;
msg.payload = "";
node.status({text: state});
return [msg, null];

if (typeof msg.statusCode !== "number" || msg.statusCode >= 400) {
    msg.statusCode = 502;
}
delete msg.headers;
return msg;

msg.url = "http://" + flow.get("esp_ip") + "/STATUS";
msg.method = "GET";
msg.requestTimeout = 1500;
msg.payload = "";
return msg;

if (typeof msg.statusCode !== "number" || msg.statusCode >= 400) {
    msg.statusCode = 502;
    msg.payload = {error: "ESP32 not reachable"};
    node.status({fill: "red", shape: "ring", text: "ESP32 offline"});
} else {
    node.status({fill: "green", shape: "dot", text: msg.payload});
}
msg.headers = {"Content-Type": "application/json"};
return msg;

msg.url = flow.get("api") + "/api/status";
msg.method = "GET";
msg.requestTimeout = 1500;
msg.payload = "";
return msg;

// Python ka live status: Dashboard + Settings ko har second, Charts ko har 10 second
const api = msg.payload;
if (msg.statusCode !== 200 || typeof api !== "object") {
    node.status({fill: "red", shape: "ring", text: "main.py not running"});
    const offline = {topic: "status", payload: {offline: true}};
    return [offline, offline, null];
}
node.status({fill: "green", shape: "dot", text: api.time});
api.esp_ip = flow.get("esp_ip");
const out = {topic: "status", payload: api};

let charts = null;
if (Date.now() - (context.get("charts_at") || 0) >= 10000) {
    context.set("charts_at", Date.now());
    charts = out;
}
return [out, out, charts];

msg.url = flow.get("api") + "/api/history?hours=" + (flow.get("range_h") || 6);
msg.method = "GET";
msg.requestTimeout = 15000;
msg.payload = "";
return msg;

if (msg.statusCode !== 200 || typeof msg.payload !== "object") return null;
msg.topic = "history";
return msg;

msg.url = flow.get("api") + "/api/days?n=7";
msg.method = "GET";
msg.requestTimeout = 15000;
msg.payload = "";
return msg;

if (msg.statusCode !== 200 || typeof msg.payload !== "object") return null;
msg.topic = "days";
return msg;

msg.url = flow.get("api") + "/api/report?month=" + (flow.get("report_month") || "");
msg.method = "GET";
msg.requestTimeout = 20000;
msg.payload = "";
return msg;

if (msg.statusCode !== 200 || typeof msg.payload !== "object") return null;
msg.topic = "report";
return msg;

// Pages se aaye actions: mode / threshold / chart range / report month
const post = (path, body) => ({url: flow.get("api") + path, method: "POST", requestTimeout: 5000,
                               headers: {"Content-Type": "application/json"}, payload: body});
switch (msg.topic) {
    case "mode":
        return [post("/api/device/" + msg.device, {mode: msg.payload}), null, null, null];
    case "threshold":
        return [post("/api/settings", {fan_threshold: msg.payload}), null, null, null];
    case "range":
        flow.set("range_h", Number(msg.payload) || 6);
        return [null, {}, {}, null];
    case "month":
        flow.set("report_month", msg.payload);
        return [null, null, null, {}];
}
return null;
